//! The IEC 61970/61968 Common Information Model as profiled by ENTSO-E CGMES:
//! typed structs for every class, the streaming RDF/XML decoder that builds a
//! [`CimDataset`], and conversion back to RDF/XML and to JSON.
//!
//! The structs and their tables are generated by `cimgen` into `src/generated/`
//! (gitignored; run `make generate`) and re-exported here, so a class is
//! `cimmodel::Terminal` and a table `cimmodel::registry`. Everything else in
//! `src/` is hand-written.

pub mod base;
pub mod convert;
pub mod decode;
pub mod schema_source;

mod generated;
pub use generated::*;

pub use decode::{CimDataset, CimEntry};
